// Search/social metadata for synced handbook pages. src/content/handbook/ is
// generated by `npm run sync` and never hand-edited, so the description comes
// from (in order) src/data/handbook-seo.yaml, frontmatter `description`, or the
// opening prose of the Markdown body.
import yaml from "js-yaml";
import rawOverrides from "../../data/handbook-seo.yaml?raw";
import { SECTION_NAMES, type SectionSlug } from "../sections";
import { composeTitle, describeMarkdown } from "./index";
import type { OgCard } from "./pages";

const overrides = (yaml.load(rawOverrides) ?? {}) as Record<string, { description?: string }>;

export interface HandbookEntryLike {
  id: string;
  body?: string;
  data: { title: string; section: SectionSlug; description?: string; syncedAt: string };
}

export function handbookSeo(page: HandbookEntryLike) {
  const sectionName = SECTION_NAMES[page.data.section];
  const description =
    overrides[page.id]?.description ??
    page.data.description ??
    describeMarkdown(page.body ?? "") ??
    `${page.data.title}：數位韌性手冊「${sectionName}」篇的一頁，內容同步自 g0v 數位韌性松在 HackMD 上的原始共筆。`;
  const og: OgCard = { heading: page.data.title, kicker: `手冊 · ${sectionName}` };
  return {
    title: composeTitle(page.data.title, "handbook"),
    description,
    sectionName,
    og,
    /** Last sync from HackMD (sync metadata) — also dateModified in JSON-LD. */
    modified: page.data.syncedAt,
  };
}
